<?php } elseif($page==='apply'){ $type=($_GET['type']??'academy')==='first_team'?'first_team':'academy';$fields=fetch_all('SELECT * FROM form_fields WHERE form_type=? AND active=1 ORDER BY sort_order,id',[$type]);$ok='';$err='';if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf();$data=[];foreach($fields as $f){$v=trim((string)($_POST[$f['name']]??''));if($f['required']&&!$v)throw new RuntimeException($f['label'].' zorunludur.');$data[$f['label']]=$v;}db()->prepare('INSERT INTO applications(form_type,data_json) VALUES(?,?)')->execute([$type,json_encode($data,JSON_UNESCAPED_UNICODE)]);$ok='Başvurunuz alınmıştır.';}catch(Throwable $x){$err=$x->getMessage();}}?><section class="page-head"><small>BAŞVURU</small><h1><?=$type==='academy'?'Altyapı':'A Takım'?> Başvurusu</h1></section><section class="form-wrap"><?php if($ok):?><div class="success"><?=e($ok)?></div><?php endif?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php foreach($fields as $f):?><label><?=e($f['label'])?><?=$f['required']?' *':''?><?php if($f['field_type']==='textarea'):?><textarea name="<?=e($f['name'])?>" <?=$f['required']?'required':''?>></textarea><?php else:?><input type="<?=e($f['field_type'])?>" name="<?=e($f['name'])?>" <?=$f['required']?'required':''?>><?php endif?></label><?php endforeach?><button class="btn">Başvuruyu Gönder</button></form></section><?php }
